package com.example.starter.observation;

import java.time.Instant;

/**
 * 采样许可领域记录：对应 sampling_permit 表的一行。
 *
 * <p>许可授权一台设备在一片连续整数网格区间 {@code [gridMin, gridMax]} 与
 * 一个 UTC 左闭右开时间窗 {@code [validFromUtc, validToUtc)} 内采样至多 {@code maxObservations} 条。
 * 提前结束仅把有效窗口上界改为 {@code terminatedAtUtc}（不含该时刻），不改变其余字段。
 *
 * @param permitId       许可唯一标识
 * @param deviceId       被授权设备标识
 * @param permitVersion  许可版本，创建后不可变
 * @param gridMin        授权网格区间下界（闭区间，单位：网格单元编号）
 * @param gridMax        授权网格区间上界（闭区间，单位：网格单元编号）
 * @param validFromUtc   有效期起点（UTC，含）
 * @param validToUtc     有效期终点（UTC，不含）
 * @param terminatedAtUtc 提前结束时刻（UTC，不含）；null 表示未提前结束
 * @param revokedAtUtc   撤销时刻（UTC）；null 表示未撤销
 * @param status         许可状态
 * @param maxObservations 最大观测数（单位：条）
 * @param observedCount  已接收观测计数（单位：条）
 */
public record SamplingPermit(
        String permitId,
        String deviceId,
        String permitVersion,
        int gridMin,
        int gridMax,
        Instant validFromUtc,
        Instant validToUtc,
        Instant terminatedAtUtc,
        Instant revokedAtUtc,
        PermitStatus status,
        int maxObservations,
        int observedCount) {

    /**
     * 当前实际有效窗口上界（UTC，不含）：取提前结束时刻与原定终点的较早者。
     */
    public Instant effectiveValidToUtc() {
        return terminatedAtUtc == null || terminatedAtUtc.isAfter(validToUtc)
                ? validToUtc
                : terminatedAtUtc;
    }

    /**
     * 许可是否可能在给定时刻命中：状态为 ACTIVE 且时刻落在左闭右开有效窗口内。
     */
    public boolean covers(Instant atUtc) {
        return status == PermitStatus.ACTIVE
                && !atUtc.isBefore(validFromUtc)
                && atUtc.isBefore(effectiveValidToUtc());
    }

    /**
     * 许可是否覆盖给定网格单元（闭区间）。
     */
    public boolean coversGrid(int gridId) {
        return gridId >= gridMin && gridId <= gridMax;
    }

    /**
     * 是否完整覆盖目标网格区间（批量坐标边界预校验使用）。
     */
    public boolean coversGridRange(int minGridId, int maxGridId) {
        return minGridId >= gridMin && maxGridId <= gridMax;
    }
}

package com.example.starter.observation;

import java.time.Instant;

/**
 * 采样许可纯规则：网格与 UTC 左闭右开时间窗的覆盖、相交与命中判定，不访问数据库与时钟，可独立单测。
 */
public final class PermitRules {

    private PermitRules() {
    }

    /**
     * 整数闭区间网格是否相交（端点相接也算相交：网格单元为离散编号，共享单元即重叠）。
     */
    public static boolean gridIntersects(int minA, int maxA, int minB, int maxB) {
        return minA <= maxB && minB <= maxA;
    }

    /**
     * 两个左闭右开时间窗是否相交：共享任意时刻即重叠；{@code [a,b)} 与 {@code [b,c)} 仅在端点相接，不相交。
     */
    public static boolean timeIntersects(Instant fromA, Instant toA, Instant fromB, Instant toB) {
        return fromA.isBefore(toB) && fromB.isBefore(toA);
    }

    /**
     * 两张许可的“有效”授权区域是否在网格与时间两个维度同时相交（同设备重叠检测）。
     * 以创建参数的原定窗口与网格区间比较：提前结束只缩小窗口，许可创建时均无提前结束。
     */
    public static boolean overlaps(SamplingPermit existing, int gridMin, int gridMax,
                                   Instant validFromUtc, Instant validToUtc) {
        if (existing.status() != PermitStatus.ACTIVE) {
            return false;
        }
        return gridIntersects(existing.gridMin(), existing.gridMax(), gridMin, gridMax)
                && timeIntersects(existing.validFromUtc(), existing.effectiveValidToUtc(),
                validFromUtc, validToUtc);
    }

    /**
     * 许可是否命中给定采样点：状态 ACTIVE、网格落在闭区间、时刻落在左闭右开窗口。
     */
    public static boolean matches(SamplingPermit permit, String deviceId, int gridId, Instant observedAtUtc) {
        return permit.status() == PermitStatus.ACTIVE
                && permit.deviceId().equals(deviceId)
                && permit.coversGrid(gridId)
                && permit.covers(observedAtUtc);
    }

    /**
     * 许可创建参数的时间窗是否合法：起点必须早于终点，且起点不得早于当前时刻（禁止追溯许可）。
     */
    public static boolean isValidCreateRange(Instant validFromUtc, Instant validToUtc, Instant nowUtc) {
        return validFromUtc != null && validToUtc != null
                && validFromUtc.isBefore(validToUtc)
                && !validFromUtc.isBefore(nowUtc);
    }
}

